-- A stock move is never changed or removed, whoever asks, the table's owner included; a wrong
-- one is undone by an opposite move. The one exception is the same as the ledger's: a session
-- signed in as postgres itself may delete the rows of the companies it has named in
-- app.purge_tenants for that transaction, which is how the tests remove their synthetic
-- companies. Balances follow the moves and are removed with them.
CREATE FUNCTION app.refuse_stock_change() RETURNS trigger
  LANGUAGE plpgsql SET search_path = ''
  AS $$
BEGIN
  IF TG_OP = 'DELETE'
     AND session_user = 'postgres'
     AND OLD.tenant_id::text = ANY (string_to_array(coalesce(current_setting('app.purge_tenants', true), ''), ','))
  THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'a stock move is never changed or removed; it is undone by an opposite move' USING ERRCODE = 'SE062';
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.refuse_stock_change() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER stock_moves_immutable
  BEFORE UPDATE OR DELETE ON public.stock_moves
  FOR EACH ROW EXECUTE FUNCTION app.refuse_stock_change();
--> statement-breakpoint
ALTER TABLE public.stock_moves ENABLE ALWAYS TRIGGER stock_moves_immutable;
--> statement-breakpoint
CREATE TRIGGER stock_moves_no_truncate
  BEFORE TRUNCATE ON public.stock_moves
  FOR EACH STATEMENT EXECUTE FUNCTION app.refuse_stock_change();
--> statement-breakpoint
ALTER TABLE public.stock_moves ENABLE ALWAYS TRIGGER stock_moves_no_truncate;
