-- One move, in or out, and the balance it leaves. Not for the app to call: only the posting
-- functions below reach it. A move out is valued here, at the weighted-average cost of what the
-- warehouse holds at this moment, and is refused when the warehouse does not hold enough
-- (SE060): stock never goes below zero. A move in brings its own value. The balance row is
-- held until the transaction ends, so two moves of one item in one warehouse take their turn.
-- Returns the value of the move, above zero.
CREATE FUNCTION app.move_stock(
  p_tenant uuid, p_user uuid, p_item uuid, p_warehouse uuid, p_date date, p_quantity numeric, p_value_in numeric,
  p_source_type text, p_source_id uuid, p_source_line_id uuid, p_reverses_move_id uuid DEFAULT NULL
) RETURNS numeric
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_quantity numeric;
  v_value numeric;
  v_move_value numeric;
  v_code text;
BEGIN
  IF p_quantity IS NULL OR p_quantity = 0 OR p_quantity = 'NaN'::numeric OR p_quantity <> round(p_quantity, 4) THEN
    RAISE EXCEPTION 'a stock move has a quantity, to at most four decimals' USING ERRCODE = 'check_violation';
  END IF;
  INSERT INTO public.stock_balances (tenant_id, item_id, warehouse_id) VALUES (p_tenant, p_item, p_warehouse)
    ON CONFLICT (tenant_id, item_id, warehouse_id) DO NOTHING;
  SELECT b.quantity, b.value INTO v_quantity, v_value FROM public.stock_balances b
    WHERE b.tenant_id = p_tenant AND b.item_id = p_item AND b.warehouse_id = p_warehouse
    FOR UPDATE;
  IF p_quantity > 0 THEN
    IF p_value_in IS NULL OR p_value_in < 0 OR p_value_in = 'NaN'::numeric OR p_value_in <> round(p_value_in, 4) THEN
      RAISE EXCEPTION 'goods coming in bring their value, to at most four decimals' USING ERRCODE = 'check_violation';
    END IF;
    v_move_value := p_value_in;
    v_quantity := v_quantity + p_quantity;
    v_value := v_value + v_move_value;
  ELSE
    IF v_quantity < -p_quantity THEN
      SELECT i.code INTO v_code FROM public.items i WHERE i.tenant_id = p_tenant AND i.id = p_item;
      RAISE EXCEPTION 'not enough of % in stock: % on hand, % needed', v_code, v_quantity, -p_quantity USING ERRCODE = 'SE060';
    END IF;
    -- The last of the stock takes the last of its value, so nothing is left behind by rounding.
    IF v_quantity = -p_quantity THEN
      v_move_value := v_value;
    ELSE
      -- Rounded to the paisa, and never more than the stock is worth.
      v_move_value := least(round(v_value * (-p_quantity) / v_quantity, 2), v_value);
    END IF;
    v_quantity := v_quantity + p_quantity;
    v_value := v_value - v_move_value;
  END IF;
  INSERT INTO public.stock_moves (tenant_id, item_id, warehouse_id, move_date, quantity, value, source_type, source_id, source_line_id, reverses_move_id, quantity_after, value_after, created_by)
    VALUES (p_tenant, p_item, p_warehouse, p_date, p_quantity, sign(p_quantity) * v_move_value, p_source_type, p_source_id, p_source_line_id, p_reverses_move_id, v_quantity, v_value, p_user);
  UPDATE public.stock_balances b SET quantity = v_quantity, value = v_value, updated_at = now()
    WHERE b.tenant_id = p_tenant AND b.item_id = p_item AND b.warehouse_id = p_warehouse;
  RETURN v_move_value;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.move_stock(uuid, uuid, uuid, uuid, date, numeric, numeric, text, uuid, uuid, uuid) FROM PUBLIC;
--> statement-breakpoint
